-- Migration 18 — category -> tag pre-fill (ADR-002 section 6)
-- GENERATED by scripts/gen_tag_defaults_migration.mjs from wardrobe_taxonomy.js
-- — edit CATEGORY_DEFAULTS in the module and regenerate, never this file.
-- Run once in the Supabase SQL editor on Robes_p0, AFTER migration 17.
-- Re-running is safe: the seed is an upsert, the backfill only touches rows
-- still carrying source 'inferred', and the trigger is create-or-replace.
--
-- WHY THIS IS IN THE DATABASE AND NOT THE CLIENT. The pre-fill has two
-- callers — the one-shot backfill of the existing wardrobe, and every future
-- insert — and implementing it twice guarantees they drift. A trigger is one
-- implementation covering both, and it cannot be bypassed by a client that
-- forgets to apply it. The mapping still lives in wardrobe_taxonomy.js; this
-- file is its compiled form.
--
-- WHAT IT DOES NOT DO. It never overwrites a value she set: both the backfill
-- and the trigger write source 'inferred' only, and skip any row already
-- marked 'user'. Correcting a pre-filled piece is therefore permanent, and
-- the inferred/user split is the correction-rate signal ADR-002 section 6
-- promises.

-- ── preflight ───────────────────────────────────────────────────────────
do $$
begin
  if not exists (select 1 from information_schema.columns
                 where table_schema = 'public' and table_name = 'wardrobe_items'
                   and column_name = 'season_band') then
    raise exception 'ADR-002: migration 17 has not run — apply supabase/season_tags_migration.sql first.';
  end if;
  if to_regclass('public.wardrobe_taxonomy') is null then
    raise exception 'ADR-002: migration 15 has not run — apply supabase/wardrobe_taxonomy_migration.sql first (the pre-fill keys on L2).';
  end if;
end $$;

-- ── the compiled mapping ────────────────────────────────────────────────
-- (sheet_l1, l2) -> the band and wear slugs a newly filed piece starts with.
-- A null l2 row is the fallback for that sheet category, and also covers
-- pieces filed before migration 15, which carry no L2 at all.
create table if not exists public.wardrobe_tag_defaults (
  sheet_l1    text not null,
  l2          text,
  season_band text not null,
  wear_slugs  text[] not null
);

create unique index if not exists idx_tag_defaults_key
  on public.wardrobe_tag_defaults (sheet_l1, coalesce(l2, ''));

alter table public.wardrobe_tag_defaults enable row level security;
do $$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'public' and tablename = 'wardrobe_tag_defaults' and policyname = 'tag_defaults_read'
  ) then
    create policy tag_defaults_read on public.wardrobe_tag_defaults
      for select to authenticated using (true);
  end if;
end $$;

