-- The seven seed labels, so the trigger can mint a tags row with the right
-- display text. Not pre-created per account — minted on first use.
create table if not exists public.wear_seed_labels (
  slug  text primary key,
  label text not null
);
insert into public.wear_seed_labels (slug, label) values
  ('everyday', 'Everyday'),
  ('work', 'Work'),
  ('evening', 'Evening'),
  ('occasion', 'Occasion'),
  ('travel', 'Travel'),
  ('active', 'Active'),
  ('lounge', 'Lounge')
on conflict (slug) do update set label = excluded.label;

-- ── resolve a piece to its defaults ─────────────────────────────────────
-- Sheet category comes from the L2 when there is one (the L2 name is unique
-- tree-wide, so it recovers its sheet category on its own), else from the
-- legacy `category` column. Mirrors _waSheetCatOf on the client.
create or replace function public.rb_piece_defaults(p_category text, p_l2 text)
returns table (season_band text, wear_slugs text[])
language sql
stable
as $fn$
  with sheet as (
    select coalesce(
      (select t.sheet_l1 from public.wardrobe_taxonomy t where t.l2 = p_l2 limit 1),
      p_category
    ) as sheet_l1
  )
  select d.season_band, d.wear_slugs
  from sheet s
  join public.wardrobe_tag_defaults d
    on d.sheet_l1 = s.sheet_l1
   and coalesce(d.l2, '') = coalesce(
         (select t.l2 from public.wardrobe_taxonomy t where t.l2 = p_l2 limit 1), '')
  limit 1;
$fn$;

-- ── apply them to one piece ─────────────────────────────────────────────
-- SECURITY DEFINER so the writes into tags/tag_pieces cannot trip an RLS
-- check from whatever context the insert arrived in; user_id is taken from
-- the piece row itself, never from auth.uid(), so it cannot cross accounts.
create or replace function public.rb_apply_tag_defaults(p_item_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $fn$
declare
  it     record;
  def    record;
  v_slug text;   -- v_ prefix: a bare `slug` would be ambiguous against the
  v_tid  uuid;   -- slug COLUMN inside the statements below
begin
  select id, user_id, category, category_l2, season_source
    into it from public.wardrobe_items where id = p_item_id;
  if not found then return; end if;

  select * into def from public.rb_piece_defaults(it.category, it.category_l2);
  if not found then return; end if;

  -- The two axes are guarded SEPARATELY. Guarding the whole function on
  -- season_source would mean that picking a season while adding a piece
  -- silently suppressed its wear pre-fill too — two unrelated decisions
  -- coupled by an early return.
  if it.season_source <> 'user' then
    update public.wardrobe_items
       set season_band = def.season_band, season_source = 'inferred'
     where id = it.id;
  end if;

  foreach v_slug in array def.wear_slugs loop
    insert into public.tags (user_id, kind, label, slug, is_seed)
    values (
      it.user_id, 'wear_for',
      coalesce((select l.label from public.wear_seed_labels l where l.slug = v_slug),
               initcap(v_slug)),
      v_slug, true)
    on conflict (user_id, kind, slug) do nothing;

    select t.id into v_tid from public.tags t
     where t.user_id = it.user_id and t.kind = 'wear_for' and t.slug = v_slug;

    if v_tid is not null then
      insert into public.tag_pieces (wardrobe_item_id, tag_id, source)
      values (it.id, v_tid, 'inferred')
      on conflict do nothing;
    end if;
  end loop;
end $fn$;

-- ── future inserts ──────────────────────────────────────────────────────
-- AFTER INSERT rather than BEFORE: the function writes to tags/tag_pieces as
-- well as the piece, and tag_pieces needs the row to exist first.
create or replace function public.rb_tag_defaults_trg()
returns trigger
language plpgsql
security definer
set search_path = public
as $fn$
begin
  perform public.rb_apply_tag_defaults(new.id);
  return null;
end $fn$;

drop trigger if exists trg_wardrobe_tag_defaults on public.wardrobe_items;
create trigger trg_wardrobe_tag_defaults
  after insert on public.wardrobe_items
  for each row execute function public.rb_tag_defaults_trg();

-- ── one-shot backfill of the existing wardrobe ──────────────────────────
-- Only rows still at source 'inferred'; anything she has corrected is left
-- exactly as it is.
--
-- NOTE the deliberate asymmetry with the trigger. rb_apply_tag_defaults
-- guards the two axes separately, so an INSERT that arrives with a chosen
-- season still gets its wear pre-fill — at insert time there is no prior tag
-- set to respect. The backfill skips a user-touched row ENTIRELY, because
-- there may well be one: adding 'everyday' on top of a piece she has
-- deliberately tagged 'work' alone would be editing her work, not filling a
-- blank. Same function, different caller, different risk.
do $$
declare r record; n bigint := 0;
begin
  for r in select id from public.wardrobe_items where season_source <> 'user' loop
    perform public.rb_apply_tag_defaults(r.id);
    n := n + 1;
  end loop;
  raise notice 'ADR-002 migration 18 complete (rev 2026-08-12a): pre-fill applied to % piece(s).', n;
end $$;

